"""Packet model for network simulation."""

from dataclasses import dataclass, field
from typing import List, Optional


@dataclass
class Packet:
    """A network packet traversing the simulated topology."""
    src_ip: str
    dst_ip: str
    size_bytes: int = 1500
    protocol: str = "ICMP"
    ttl: int = 64


@dataclass
class PacketTrace:
    """Records the path a packet takes through the network."""
    packet: Packet
    hops: List[str] = field(default_factory=list)
    total_delay_ms: float = 0.0
    delivered: bool = False

    def add_hop(self, node_name: str, delay_ms: float = 0.0):
        self.hops.append(node_name)
        self.total_delay_ms += delay_ms

    @property
    def hop_count(self):
        return max(0, len(self.hops) - 1)
